def make_grid_search(n_splits: int, lambda_grid=None):
    lambda_grid = list(config.LAMBDA_GRID) if lambda_grid is None else list(lambda_grid)
    cv = StratifiedKFold(
        n_splits=n_splits,
        shuffle=config.INNER_SHUFFLE,
        random_state=config.SHUFFLE_SEED if config.INNER_SHUFFLE else None,
    )
    return GridSearchCV(
        make_pipeline(),
        param_grid={"classify__C": [1.0 / lam for lam in lambda_grid]},
        scoring=config.INNER_SCORING,
        cv=cv,
    )

