"""Search the cloned TabMini repo for parity5 references and LR training conventions."""
import os

terms = ["parity5", "logisticregression", "logistic", "conic", "mosek", "lambda", "stratifiedkfold",
         "cross_val", "shuffle", "random_state", "gridsearchcv", "sample(frac"]
hits = {t: [] for t in terms}
for root, dirs, files in os.walk("repo"):
    dirs[:] = [d for d in dirs if d not in (".git", "__pycache__", ".devcontainer")]
    for fn in files:
        path = os.path.join(root, fn)
        try:
            with open(path, encoding="utf-8", errors="ignore") as f:
                content = f.read()
        except Exception:
            continue
        low = content.lower()
        for t in terms:
            if t.lower() in low:
                for i, line in enumerate(content.splitlines(), 1):
                    if t.lower() in line.lower():
                        hits[t].append(f"{path}:{i}: {line.strip()[:140]}")

for t in terms:
    print(f"\n### '{t}' ({len(hits[t])} hits)")
    for h in hits[t][:40]:
        print("  ", h)

print("\n### non-code files in repo (possible stored results/logs)")
for root, dirs, files in os.walk("repo"):
    dirs[:] = [d for d in dirs if d not in (".git", "__pycache__")]
    for fn in files:
        if not fn.endswith((".py", ".md", ".txt", ".sh", ".yml", ".json", ".ipynb", ".dockerignore", ".gitignore")):
            print("  ", os.path.join(root, fn))

