def verify_against_repo_data(X: pd.DataFrame, y01: np.ndarray) -> dict:
    """Cross-check our prepared data against the data files shipped in the released
    TabMini repository (plotting/data/1/parity5/{X,y}.csv), which pin the exact
    row order the authors used."""
    x_path, y_path = REPO_DATA_DIR / "X.csv", REPO_DATA_DIR / "y.csv"
    if not (x_path.exists() and y_path.exists()):
        return {"repo_data_present": False, "matches_repo_data": None}
    X_repo = pd.read_csv(x_path)
    y_repo = pd.read_csv(y_path)
    x_match = X_repo.reset_index(drop=True).astype(int).equals(X.reset_index(drop=True).astype(int))
    y_match = y_repo.iloc[:, 0].astype(int).reset_index(drop=True).equals(pd.Series(y01).astype(int))
    return {
        "repo_data_present": True,
        "matches_repo_data": bool(x_match and y_match),
        "repo_data_source": "github.com/RicardoKnauer/TabMini @ plotting/data/1/parity5",
    }

